package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionHoursInfoVO;

class RetentionHoursInfoValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention hours info of observability config")
  void test_retention_hours_info_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionHoursInfoValueHolder<Object> value = new RetentionHoursInfoValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionHoursInfo(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionHoursInfoValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionHoursInfo().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention hours info of observability config")
  void test_retention_hours_info_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionHoursInfoValueHolder<Object> value = new RetentionHoursInfoValueHolder<>(holder);
    RetentionHoursInfoVO vo = RetentionHoursInfoVO.from(1);
    Assertions.assertFalse(value.getRetentionHoursInfoValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionHoursInfo(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionHoursInfoValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionHoursInfo(Optional.empty()));
    Assertions.assertFalse(value.getRetentionHoursInfoValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionHoursInfo(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionHoursInfoValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention hours info of observability config against the original")
  void test_retention_hours_info_value_holder_read() {
    Object holder = new Object();
    RetentionHoursInfoValueHolder<Object> value = new RetentionHoursInfoValueHolder<>(holder);
    RetentionHoursInfoVO vo = RetentionHoursInfoVO.from(1);
    RetentionHoursInfoVO other = RetentionHoursInfoVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionHoursInfoValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionHoursInfo(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionHoursInfo(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionHoursInfo(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionHoursInfo(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionHoursInfo(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention hours info of observability config")
  void test_retention_hours_info_value_holder_unset() {
    Object holder = new Object();
    RetentionHoursInfoValueHolder<Object> value = new RetentionHoursInfoValueHolder<>(holder);
    RetentionHoursInfoVO vo = RetentionHoursInfoVO.from(1);
    value.retentionHoursInfo(vo);
    Assertions.assertSame(holder,
        value.unsetRetentionHoursInfoIfMatches("retentionHoursInfo_other"));
    Assertions.assertTrue(value.getRetentionHoursInfoValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionHoursInfoIfMatches("retentionHoursInfo"));
    Assertions.assertFalse(value.getRetentionHoursInfoValue().isPresent(),
        "The field name must clear the value");
    value.retentionHoursInfo(vo);
    Assertions.assertSame(holder, value.unsetRetentionHoursInfo());
    Assertions.assertFalse(value.getRetentionHoursInfoValue().isPresent(),
        "Unset must clear the value");
  }
}
